<?php
session_start();mysqli_report(MYSQLI_REPORT_OFF);
$db=new mysqli('localhost','root','','foodie');$db->set_charset('utf8mb4');
define('CSS',"body{font-family:sans-serif;margin:0;background:#fafafa}header{background:#e23744;padding:10px 16px;display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center}header a{color:#fff;text-decoration:none;margin:0 6px}.logo{font-size:22px;font-weight:700}main{max-width:1000px;margin:auto;padding:16px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:14px}.card{background:#fff;border-radius:10px;padding:10px;box-shadow:0 1px 4px #0002}.card img,.ph{width:100%;height:130px;object-fit:cover;border-radius:8px;background:#fde;display:flex;align-items:center;justify-content:center;font-size:48px}.btn,button{background:#e23744;color:#fff;border:0;padding:7px 12px;border-radius:6px;text-decoration:none;cursor:pointer;display:inline-block}input,select,textarea{width:100%;padding:8px;margin:4px 0 10px;box-sizing:border-box}table{width:100%;border-collapse:collapse;background:#fff}td,th{padding:8px;border-bottom:1px solid #eee;text-align:left}.old{text-decoration:line-through;color:#999}.banner{background:linear-gradient(90deg,#e23744,#ff8a00);color:#fff;padding:40px 20px;border-radius:12px;text-align:center}footer{text-align:center;padding:20px;color:#666}.msg{background:#ffe;padding:8px;margin:8px 0}.side{width:170px;background:#222;min-height:100vh;float:left}.side a{display:block;color:#fff;padding:12px;text-decoration:none}.adm{margin-left:170px;padding:16px;overflow-x:auto}.box{background:#fff;padding:16px;margin:6px;border-radius:8px;display:inline-block;min-width:140px;box-shadow:0 1px 4px #0002}");
function e($s){return htmlspecialchars($s??'');}
function v($a,$k){return e($a[$k]??'');}
function q($sql,$t='',...$p){$s=$GLOBALS['db']->prepare($sql);if($t)$s->bind_param($t,...$p);$s->execute();return $s;}
function rows($sql,$t='',...$p){return q($sql,$t,...$p)->get_result()->fetch_all(MYSQLI_ASSOC);}
function row($sql,$t='',...$p){return rows($sql,$t,...$p)[0]??null;}
function need(){if(empty($_SESSION['uid'])){header('Location: login.php?next='.urlencode(basename($_SERVER['PHP_SELF'])));exit;}}
function price($p){return round($p['price']*(1-$p['discount']/100),2);}
function img($f){return $f?"<img src='".(defined('P')?P:'')."uploads/".e($f)."'>":"<div class=ph>🍽️</div>";}
function upload($k,$old=''){if(!empty($_FILES[$k]['name'])&&preg_match('/\.(jpe?g|png|webp)$/i',$_FILES[$k]['name'])){$n=time().rand(10,99).'.'.pathinfo($_FILES[$k]['name'],PATHINFO_EXTENSION);move_uploaded_file($_FILES[$k]['tmp_name'],__DIR__.'/uploads/'.$n);return $n;}return $old;}
function card($p){return "<div class=card>".img($p['image'])."<h4>".e($p['name'])."</h4><small>".e(substr($p['description'],0,60))."</small><p><b>₹".number_format(price($p))."</b> ".($p['discount']>0?"<span class=old>₹".number_format($p['price'])."</span> ".(float)$p['discount']."% off":'')."</p><form method=post action=cart.php><input type=hidden name=add value={$p['id']}><button>Add to Cart</button> <a class=btn href='product.php?id={$p['id']}'>Details</a></form></div>";}
function grid($sql){echo"<div class=grid>";foreach(rows($sql) as $p)echo card($p);echo"</div>";}
function items(){$r=[];foreach($_SESSION['cart']??[] as $id=>$n)if($p=row("SELECT * FROM products WHERE id=? AND status=1",'i',$id)){$p['qty']=$n;$p['sub']=round(price($p)*$n,2);$r[]=$p;}return $r;}
function total($it){return array_sum(array_column($it,'sub'));}
function head($t){$c=array_sum($_SESSION['cart']??[]);echo"<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'><title>".e($t)." - FoodieGo</title><style>".CSS."</style><header><a class=logo href=index.php>🍔 FoodieGo</a><nav><a href=index.php>Home</a><a href=categories.php>Menu</a><a href=about.php>About</a><a href=contact.php>Contact</a>".(isset($_SESSION['uid'])?"<a href=profile.php>Profile</a><a href=orders.php>Orders</a><a href=logout.php>Logout</a>":"<a href=login.php>Login</a><a href=register.php>Register</a>")."<a href=cart.php>🛒 $c</a></nav></header><main>";}
function foot(){echo"</main><footer>© FoodieGo · <a href=about.php>About</a> · <a href=contact.php>Contact</a> · <a href=orders.php>My Orders</a></footer>";}
function ahead($t){if(empty($_SESSION['aid'])){header('Location: login.php');exit;}echo"<!doctype html><meta name=viewport content='width=device-width,initial-scale=1'><style>".CSS."</style><div class=side><h3 style='color:#fff;padding:0 12px'>Admin</h3><a href=index.php>Dashboard</a><a href=users.php>Users</a><a href=categories.php>Categories</a><a href=products.php>Products</a><a href=orders.php>Orders</a><a href=logout.php>Logout</a></div><div class=adm><h2>$t</h2>";}
function orderView($o){echo"<p>Order #{$o['id']} · {$o['created_at']}<br>".e($o['name'])." · ".e($o['email'])." · ".e($o['mobile'])."<br>".e($o['address']).", ".e($o['city']).", ".e($o['state'])." - ".e($o['pincode'])."<br>Payment: {$o['payment_method']} ({$o['payment_status']}) · Status: {$o['status']}</p><table><tr><th>Item<th>Price<th>Qty</tr>";foreach(rows("SELECT * FROM order_items WHERE order_id=?",'i',$o['id']) as $i)echo"<tr><td>".e($i['name'])."<td>₹".number_format($i['price'])."<td>{$i['qty']}</tr>";echo"</table><h3>Total ₹".number_format($o['total'])."</h3>";}
